<?php
require_once __DIR__ . '/../app/layout.php';$u=require_login();$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='create'){
   if(!in_array($u['role'],['admin','ngo'],true))throw new RuntimeException('Only admins and NGO accounts can create campaigns.');
   if($u['role']==='ngo'&&$u['verification_status']!=='verified')throw new RuntimeException('Your NGO must be verified before creating a campaign.');
   $title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$type=trim($_POST['emergency_type']??'');$area=trim($_POST['area']??'');$target=(float)($_POST['target_quantity']??0);$unit=$_POST['unit']??'kg';$start=$_POST['start_at']??'';$end=$_POST['end_at']??'';$status=$u['role']==='admin'?'active':'draft';
   if($title===''||$type===''||$area===''||$target<0||!in_array($unit,['kg','portion','meal','box'],true)||!$start||!$end||strtotime($end)<=strtotime($start))throw new RuntimeException('Enter a title, emergency type, area, valid target, and end time after start time.');
   $pdo->prepare('INSERT INTO relief_campaigns(title,description,emergency_type,area,target_quantity,unit,start_at,end_at,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$title,$desc,$type,$area,$target,$unit,str_replace('T',' ',$start).':00',str_replace('T',' ',$end).':00',$status,$u['id']]);$id=(int)$pdo->lastInsertId();audit((int)$u['id'],'campaign_created','relief_campaigns',$id,$title);flash('Campaign created'.($status==='draft'?' as draft.':' and published.'));redirect('campaigns.php');
  }elseif($action==='join'){
   if($u['role']!=='ngo'||$u['verification_status']!=='verified')throw new RuntimeException('Only verified NGO accounts can join campaigns.');$cid=(int)($_POST['campaign_id']??0);$q=$pdo->prepare("SELECT id FROM relief_campaigns WHERE id=? AND status='active' AND end_at>=NOW()");$q->execute([$cid]);if(!$q->fetch())throw new RuntimeException('Campaign is not active.');$pdo->prepare("INSERT INTO campaign_participants(campaign_id,ngo_id,status) VALUES(?,?,'joined') ON DUPLICATE KEY UPDATE status='joined',joined_at=NOW()")->execute([$cid,$u['id']]);flash('Your NGO joined the campaign.');redirect('campaigns.php');
  }elseif($action==='status'){
   $cid=(int)($_POST['campaign_id']??0);$status=$_POST['status']??'';if(!in_array($status,['active','paused','completed','cancelled'],true))throw new RuntimeException('Invalid campaign status.');$q=$pdo->prepare('SELECT * FROM relief_campaigns WHERE id=?');$q->execute([$cid]);$c=$q->fetch();if(!$c||($u['role']!=='admin'&&(int)$c['created_by']!==(int)$u['id']))throw new RuntimeException('You cannot manage this campaign.');if($u['role']!=='admin'&&$status==='active')throw new RuntimeException('Only an admin can publish a campaign.');$pdo->prepare('UPDATE relief_campaigns SET status=? WHERE id=?')->execute([$status,$cid]);audit((int)$u['id'],'campaign_status_changed','relief_campaigns',$cid,$status);flash('Campaign status updated.');redirect('campaigns.php');
  }elseif($action==='allocate'){
   $cid=(int)($_POST['campaign_id']??0);$foodId=(int)($_POST['surplus_food_id']??0);$qty=(float)($_POST['quantity']??0);if($qty<=0)throw new RuntimeException('Allocation quantity must be positive.');
   $q=$pdo->prepare('SELECT * FROM relief_campaigns WHERE id=?');$q->execute([$cid]);$c=$q->fetch();if(!$c||($u['role']!=='admin'&&(int)$c['created_by']!==(int)$u['id']))throw new RuntimeException('Only the campaign creator or admin can allocate food.');if($c['status']!=='active')throw new RuntimeException('Food can only be allocated to an active campaign.');
   $pdo->beginTransaction();$q=$pdo->prepare("SELECT sf.* FROM surplus_food sf WHERE sf.id=? AND sf.status='available' AND sf.safety_deadline>NOW() AND EXISTS(SELECT 1 FROM food_safety_checks sc WHERE sc.surplus_food_id=sf.id AND sc.result='safe') FOR UPDATE");$q->execute([$foodId]);$food=$q->fetch();if(!$food)throw new RuntimeException('Only available, unexpired, safety-approved food can be allocated.');
   $q=$pdo->prepare("SELECT COALESCE(SUM(allocated_quantity),0) FROM campaign_allocations WHERE surplus_food_id=? AND status IN ('reserved','fulfilled')");$q->execute([$foodId]);$allocated=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(quantity_kg),0) FROM donation_requests WHERE surplus_food_id=? AND status NOT IN ('rejected','cancelled')");$q->execute([$foodId]);$requested=(float)$q->fetchColumn();if($allocated+$requested+$qty>(float)$food['quantity_kg'])throw new RuntimeException('Allocation exceeds the listing quantity remaining after existing donation requests and campaign allocations.');
   $pdo->prepare("INSERT INTO campaign_allocations(campaign_id,surplus_food_id,allocated_quantity,status,created_by) VALUES(?,?,?,'reserved',?)")->execute([$cid,$foodId,$qty,$u['id']]);$pdo->commit();flash('Food allocation recorded. It remains in the normal listing workflow until a delivery is confirmed.');redirect('campaigns.php');
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Action failed. Check the migration and form data.';}
}
$campaigns=$pdo->query("SELECT c.*,u.name AS creator,(SELECT COUNT(*) FROM campaign_participants p WHERE p.campaign_id=c.id AND p.status='joined') AS ngo_count,(SELECT COALESCE(SUM(a.allocated_quantity),0) FROM campaign_allocations a WHERE a.campaign_id=c.id AND a.status IN ('reserved','fulfilled')) AS allocated FROM relief_campaigns c JOIN users u ON u.id=c.created_by ORDER BY FIELD(c.status,'active','draft','paused','completed','cancelled'),c.end_at DESC")->fetchAll();
$foods=$pdo->query("SELECT sf.id,sf.food_name,sf.quantity_kg,sf.category FROM surplus_food sf WHERE sf.status='available' AND sf.safety_deadline>NOW() AND EXISTS(SELECT 1 FROM food_safety_checks sc WHERE sc.surplus_food_id=sf.id AND sc.result='safe') ORDER BY sf.safety_deadline LIMIT 100")->fetchAll();
page_header('Emergency relief campaigns');?>
<div class="page-intro"><div class="eyebrow">COMMUNITY RESPONSE</div><h1>Relief & <em>campaigns.</em></h1><p>Coordinate emergency food drives, invite verified NGOs and record safe-food allocations without duplicating existing delivery tracking.</p></div><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?>
<?php if(in_array($u['role'],['admin','ngo'],true)):?><div class="form-panel"><h2>Create relief campaign</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Campaign title<input name="title" maxlength="180" required></label><label>Emergency type<select name="emergency_type" required><option value="flood">Flood</option><option value="cyclone">Cyclone</option><option value="community_food_drive">Community food drive</option><option value="other">Other</option></select></label><label>Area / district<input name="area" maxlength="180" required></label><label>Target quantity<input type="number" name="target_quantity" min="0" step="0.01" required value="100"></label><label>Unit<select name="unit"><option>kg</option><option>portion</option><option>meal</option><option>box</option></select></label><label>Start<input type="datetime-local" name="start_at" required value="<?=e(date('Y-m-d\TH:i'))?>"></label><label>End<input type="datetime-local" name="end_at" required value="<?=e(date('Y-m-d\TH:i',time()+7*86400))?>"></label><label class="full">Description<textarea name="description" rows="3" maxlength="5000"></textarea></label><div class="full"><button class="btn" type="submit">Create campaign</button></div></form><p class="muted">NGO-created campaigns start as drafts for admin review. Admin-created campaigns are published immediately.</p></div><?php endif;?>
<div class="section-heading"><div><div class="eyebrow">CAMPAIGN DIRECTORY</div><h2>Active & recent campaigns</h2></div></div><div class="food-grid"><?php foreach($campaigns as $c):?><article class="food-card"><div class="food-card-body"><div class="food-title-row"><h3><?=e($c['title'])?></h3><?=status_badge($c['status'])?></div><p><?=e($c['description']??'')?></p><div class="food-meta"><span>📍 <?=e($c['area'])?> · <?=e($c['emergency_type'])?></span><span>Target: <?=number_format((float)$c['target_quantity'],2)?> <?=e($c['unit'])?></span><span>Allocated: <?=number_format((float)$c['allocated'],2)?> · NGOs joined: <?=(int)$c['ngo_count']?></span><span>Ends: <?=e($c['end_at'])?></span><span>Coordinator: <?=e($c['creator'])?></span></div>
<?php if($u['role']==='ngo'&&$c['status']==='active'&&$u['verification_status']==='verified'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="join"><input type="hidden" name="campaign_id" value="<?=(int)$c['id']?>"><button class="btn btn-sm" type="submit">Join campaign</button></form><?php endif;?>
<?php if($u['role']==='admin'||(int)$c['created_by']===(int)$u['id']):?><form method="post" class="form-grid" style="margin-top:14px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="campaign_id" value="<?=(int)$c['id']?>"><label class="full">Update status<select name="status"><?php if($u['role']==='admin'):?><option value="active">Active</option><?php endif;?><option value="paused">Paused</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><div class="full"><button class="btn btn-outline btn-sm" type="submit">Save status</button></div></form><form method="post" class="form-grid" style="margin-top:12px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="allocate"><input type="hidden" name="campaign_id" value="<?=(int)$c['id']?>"><label class="full">Safe food listing<select name="surplus_food_id" required><option value="">Choose available verified food</option><?php foreach($foods as $f):?><option value="<?=(int)$f['id']?>">#<?=(int)$f['id']?> · <?=e($f['food_name'])?> (<?=e($f['quantity_kg'])?> kg)</option><?php endforeach;?></select></label><label class="full">Allocate quantity (kg)<input type="number" name="quantity" min="0.01" step="0.01" required></label><div class="full"><button class="btn btn-sm" type="submit">Record allocation</button></div></form><?php endif;?></div></article><?php endforeach;?><?php if(!$campaigns):?><div class="empty-state"><h3>No campaigns yet</h3><p>Create an emergency campaign to start coordinating a response.</p></div><?php endif;?></div><?php page_footer();?>
